int __vsock_stream_recvmsg(struct sock *sk, struct msghdr *msg, size_t len,
			   int flags);
int __vsock_seqpacket_recvmsg(struct sock *sk, struct msghdr *msg,
			      size_t len, int flags);

static int __vsock_recvmsg(struct sock *sk, struct msghdr *msg, size_t len, int flags)
{
	struct vsock_sock *vsk;
	int err;

	if (sk->sk_type == SOCK_STREAM) {
		err = __vsock_stream_recvmsg(sk, msg, len, flags);
	} else if (sk->sk_type == SOCK_SEQPACKET) {
		err = __vsock_seqpacket_recvmsg(sk, msg, len, flags);
	} else if (sk->sk_type == SOCK_DGRAM) {
		vsk = vsock_sk(sk);
		err = vsk->transport->dgram_dequeue(vsk, msg, len, flags);
	} else {
		err = -EPROTOTYPE;
	}

	return err;
}

